PRAGMA foreign_keys = ON;

-- Interaktivní self-check do knihovny testů. Bez automatického přiřazení studentům.
-- Opravy a vysvětlení vyhodnocuje server až po odeslání.
INSERT OR IGNORE INTO self_check_tests
  (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES
  ('funkce-diagnosticky-v1', 'funkce-diagnosticky', 1,
   'Funkce, definiční obor, obor hodnot a graf — diagnostický self-check',
   '[[calculator:Bez kalkulačky]]12 úloh / 22 bodů / cca 25 minut. Zaměřeno pouze na funkční předpisy, definiční obor, obor hodnot a grafy. U každé otázky vyber jednu správnou odpověď; po odeslání se zobrazí výsledek a vysvětlení.', 'Matematika', 'Funkce', 'SŠ', 25, 'published');

INSERT OR IGNORE INTO self_check_questions
  (id, test_id, position, prompt, options_json, correct_answer, explanation, points)
VALUES
  ('funkce-diagnosticky-v1-q1', 'funkce-diagnosticky-v1', 1, '{"instruction":"Která množina uspořádaných dvojic určuje funkci?","math":"","category":"Funkce a předpis","hint":"Každému vstupu x smí odpovídat právě jedna hodnota y."}', '[{"id":"a","label":"[[math:\\{(-2,1),(0,2),(0,4),(3,5)\\}]]"},{"id":"b","label":"[[math:\\{(-2,1),(0,2),(3,5)\\}]]"},{"id":"c","label":"[[math:\\{(1,0),(1,2),(2,3)\\}]]"},{"id":"d","label":"[[math:\\{(-1,0),(0,1),(0,2)\\}]]"}]', 'b', 'V každé funkci se žádný vstup x nesmí opakovat s různou výstupní hodnotou. V možnosti B má každý vstup právě jednu výstupní hodnotu.', 1),
  ('funkce-diagnosticky-v1-q2', 'funkce-diagnosticky-v1', 2, '{"instruction":"Je dána funkce. Urči hodnotu f(−2).","math":"f(x)=x^2-3x+1","category":"Funkce a předpis","hint":"Dosazuj x=−2 do každého výskytu proměnné."}', '[{"id":"a","label":"[[math:3]]"},{"id":"b","label":"[[math:5]]"},{"id":"c","label":"[[math:11]]"},{"id":"d","label":"[[math:-1]]"}]', 'c', 'Dosadíme [[math:x=-2]]: [[math:f(-2)=(-2)^2-3(-2)+1=4+6+1=11]].', 1),
  ('funkce-diagnosticky-v1-q3', 'funkce-diagnosticky-v1', 3, '{"instruction":"Který bod leží na grafu funkce?","math":"f(x)=2x-1","category":"Graf a body","hint":"Bod [[math:(x,y)]] leží na grafu, právě když [[math:y=f(x)]]."}', '[{"id":"a","label":"[[math:(0,1)]]"},{"id":"b","label":"[[math:(1,0)]]"},{"id":"c","label":"[[math:(2,3)]]"},{"id":"d","label":"[[math:(-1,1)]]"}]', 'c', 'Pro [[math:x=2]] dostaneme [[math:f(2)=2\cdot2-1=3]], takže bod [[math:(2,3)]] leží na grafu.', 1),
  ('funkce-diagnosticky-v1-q4', 'funkce-diagnosticky-v1', 4, '{"instruction":"Urči definiční obor funkce.","math":"f(x)=3x^2-5x+2","category":"Definiční obor","hint":"Polynom je definovaný pro každé reálné x."}', '[{"id":"a","label":"[[math:D(f)=\\mathbb{R}]]"},{"id":"b","label":"[[math:D(f)=\\mathbb{R}\\setminus\\{0\\}]]"},{"id":"c","label":"[[math:D(f)=[0,\\infty)]]"},{"id":"d","label":"[[math:D(f)=(-\\infty,2]]"}]', 'a', 'Polynom neobsahuje odmocninu se záporným výrazem ani jmenovatel, který by mohl být nulový. Je proto definovaný pro všechna reálná čísla.', 2),
  ('funkce-diagnosticky-v1-q5', 'funkce-diagnosticky-v1', 5, '{"instruction":"Urči definiční obor funkce.","math":"g(x)=\\frac{1}{x^2-9}","category":"Definiční obor","hint":"Jmenovatel nesmí být roven nule."}', '[{"id":"a","label":"[[math:D(g)=\\mathbb{R}\\setminus\\{-3,3\\}]]"},{"id":"b","label":"[[math:D(g)=\\mathbb{R}]]"},{"id":"c","label":"[[math:D(g)=\\mathbb{R}\\setminus\\{3\\}]]"},{"id":"d","label":"[[math:D(g)=(-3,3)]]"}]', 'a', 'Řešíme [[math:x^2-9=0]], tedy [[math:(x-3)(x+3)=0]]. Vyloučíme [[math:x=-3]] a [[math:x=3]], takže [[math:D(g)=\mathbb{R}\setminus\{-3,3\}]].', 2),
  ('funkce-diagnosticky-v1-q6', 'funkce-diagnosticky-v1', 6, '{"instruction":"Urči definiční obor funkce.","math":"h(x)=\\sqrt{2x-6}","category":"Definiční obor","hint":"Výraz pod odmocninou musí být nezáporný."}', '[{"id":"a","label":"[[math:D(h)=(-\\infty,3]]]"},{"id":"b","label":"[[math:D(h)=[3,\\infty)]]"},{"id":"c","label":"[[math:D(h)=(3,\\infty)]]"},{"id":"d","label":"[[math:D(h)=\\mathbb{R}]]"}]', 'b', 'Musí platit [[math:2x-6\ge0]], tedy [[math:2x\ge6]] a [[math:x\ge3]]. Proto [[math:D(h)=[3,\infty)]].', 2),
  ('funkce-diagnosticky-v1-q7', 'funkce-diagnosticky-v1', 7, '{"instruction":"Urči definiční obor funkce.","math":"p(x)=\\frac{\\sqrt{x+1}}{x-2}","category":"Definiční obor","hint":"Současně hlídej podmínku pro odmocninu i nenulový jmenovatel."}', '[{"id":"a","label":"[[math:D(p)=[-1,\\infty)]]"},{"id":"b","label":"[[math:D(p)=(-1,2)\\cup(2,\\infty)]]"},{"id":"c","label":"[[math:D(p)=[-1,2)\\cup(2,\\infty)]]"},{"id":"d","label":"[[math:D(p)=(-\\infty,-1]\\cup(2,\\infty)]]"}]', 'c', 'Z odmocniny plyne [[math:x+1\ge0]], tedy [[math:x\ge-1]]. Jmenovatel navíc vyžaduje [[math:x\ne2]]. Proto [[math:D(p)=[-1,2)\cup(2,\infty)]].', 2),
  ('funkce-diagnosticky-v1-q8', 'funkce-diagnosticky-v1', 8, '{"instruction":"Urči obor hodnot funkce s definičním oborem [[math:\\mathbb{R}]].","math":"f(x)=2x+5","category":"Obor hodnot","hint":"Přímka s nenulovou směrnicí nabývá při reálném x všech reálných hodnot."}', '[{"id":"a","label":"[[math:H(f)=[5,\\infty)]]"},{"id":"b","label":"[[math:H(f)=\\mathbb{R}]]"},{"id":"c","label":"[[math:H(f)=(-\\infty,5]]"},{"id":"d","label":"[[math:H(f)=\\{5\\}]]"}]', 'b', 'Pro libovolné [[math:y\in\mathbb{R}]] lze vyřešit [[math:y=2x+5]] podle x: [[math:x=(y-5)/2]]. Každé reálné y tedy funkce dosáhne.', 2),
  ('funkce-diagnosticky-v1-q9', 'funkce-diagnosticky-v1', 9, '{"instruction":"Urči obor hodnot funkce.","math":"f(x)=(x-2)^2-3,\\qquad D(f)=\\mathbb{R}","category":"Obor hodnot","hint":"Druhá mocnina je nezáporná a její nejmenší hodnota je 0."}', '[{"id":"a","label":"[[math:H(f)=(-\\infty,-3]]]"},{"id":"b","label":"[[math:H(f)=[-3,\\infty)]]"},{"id":"c","label":"[[math:H(f)=\\mathbb{R}]]"},{"id":"d","label":"[[math:H(f)=(-3,\\infty)]]"}]', 'b', 'Protože [[math:(x-2)^2\ge0]], platí [[math:f(x)\ge-3]]. Minimum [[math:-3]] nastává pro [[math:x=2]], takže [[math:H(f)=[-3,\infty)]].', 2),
  ('funkce-diagnosticky-v1-q10', 'funkce-diagnosticky-v1', 10, '{"instruction":"Urči obor hodnot funkce.","math":"g(x)=\\sqrt{x-1}+2,\\qquad D(g)=[1,\\infty)","category":"Obor hodnot","hint":"Odmocnina nabývá jen nezáporných hodnot."}', '[{"id":"a","label":"[[math:H(g)=[2,\\infty)]]"},{"id":"b","label":"[[math:H(g)=(2,\\infty)]]"},{"id":"c","label":"[[math:H(g)=\\mathbb{R}]]"},{"id":"d","label":"[[math:H(g)=(-\\infty,2]]]"}]', 'a', 'Platí [[math:\sqrt{x-1}\ge0]], tedy [[math:g(x)\ge2]]. Hodnoty 2 funkce dosáhne pro [[math:x=1]], proto [[math:H(g)=[2,\infty)]].', 2),
  ('funkce-diagnosticky-v1-q11', 'funkce-diagnosticky-v1', 11, '{"instruction":"Graf funkce je parabola otevřená dolů s vrcholem v bodě [[math:(1,-2)]]. Jaký je její obor hodnot?","math":"D(f)=\\mathbb{R}","category":"Graf a obor hodnot","hint":"U paraboly otevřené dolů je y souřadnice vrcholu největší dosaženou hodnotou."}', '[{"id":"a","label":"[[math:H(f)=[-2,\\infty)]]"},{"id":"b","label":"[[math:H(f)=(-\\infty,-2]]]"},{"id":"c","label":"[[math:H(f)=(-\\infty,-2)]]"},{"id":"d","label":"[[math:H(f)=\\mathbb{R}]]"}]', 'b', 'Parabola je otevřená dolů, a proto její vrchol určuje maximum. Největší hodnota je [[math:-2]] a je dosažena, takže [[math:H(f)=(-\infty,-2]]].', 3),
  ('funkce-diagnosticky-v1-q12', 'funkce-diagnosticky-v1', 12, '{"instruction":"Graf je přímka procházející body [[math:(-2,3)]] a [[math:(2,-1)]]. Který předpis jí odpovídá?","math":"","category":"Graf a předpis","hint":"Nejprve vypočti směrnici z obou bodů a potom dopočítej průsečík s osou y."}', '[{"id":"a","label":"[[math:f(x)=x+1]]"},{"id":"b","label":"[[math:f(x)=-x+1]]"},{"id":"c","label":"[[math:f(x)=-2x-1]]"},{"id":"d","label":"[[math:f(x)=2x-1]]"}]', 'b', 'Směrnice je [[math:\frac{-1-3}{2-(-2)}=-1]]. Dosazením bodu [[math:(2,-1)]] do [[math:y=-x+b]] vyjde [[math:b=1]], tedy [[math:f(x)=-x+1]].', 2);
